import {
  getParsedQueryStringAsObject,
  getQueryStringValue,
  setUrl,
  updatedQueryString,
} from '../url';

const mockWindow = () => {
  window.history.pushState = jest.fn();
  window.location.protocol = 'https://';
  window.location.host = 'app.joltup.com';
  window.location.pathname = '/pathname';

  return window;
};

const exampleQueryString = '?param=123&anotherparam=456';

describe('url', () => {
  it('getQueryStringValue should return value from query string by key', () => {
    expect(getQueryStringValue('param', exampleQueryString)).toBe('123');
    expect(getQueryStringValue('anotherparam', exampleQueryString)).toBe('456');
    expect(getQueryStringValue('anotherparam')).toBe(undefined);
  });

  it('updatedQueryString should return updated query string', () => {
    expect(updatedQueryString('param', 'abc', exampleQueryString)).toBe(
      '?param=abc&anotherparam=456',
    );
    expect(updatedQueryString('anotherparam', 'def', exampleQueryString)).toBe(
      '?param=123&anotherparam=def',
    );
    expect(updatedQueryString()).toBe('');
  });

  it('setUrl should call call window.history.replaceState', () => {
    const window = mockWindow();
    const spy = jest.spyOn(window.history, 'replaceState');
    const { protocol, host, pathname } = window.location;
    setUrl(exampleQueryString);
    const expectedUrl = `${protocol}//${host}${pathname}${exampleQueryString}`;
    expect(spy).toHaveBeenCalledWith(null, null, expectedUrl);
  });

  it('getParsedQueryStringAsObject should return object', () => {
    expect(getParsedQueryStringAsObject()).toEqual({
      anotherparam: '456',
      param: '123',
    });
  });
});
